insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$pocos-de-caldas$q$, $q$https://servicos.pocosdecaldas.mg.gov.br/uploads/leis/2007/decretos_8984.pdf ; https://servicos.pocosdecaldas.mg.gov.br/uploads/leis/2008/decretos_9186.pdf ; https://servicos.pocosdecaldas.mg.gov.br/uploads/leis/2012/decretos_10501.pdf ; https://servicos.pocosdecaldas.mg.gov.br/uploads/leis/1998/leisordinarias_6620.pdf ; https://servicos.pocosdecaldas.mg.gov.br/uploads/leis/1994/leisordinarias_5664.pdf (portal de Legislação Municipal; os PDFs só baixam com User-Agent de navegador)$q$, $q$Atos oficiais de Poços de Caldas: domínio público (Lei 9.610/1998, art. 8º, IV). Geometria: OpenStreetMap (ODbL 1.0, © colaboradores do OSM), vias casadas por nome; o polígono do hipercentro (registro desativado) é derivado dessas vias.$q$, 87, $q$ARC (Dec. 8.984/2007, red. Dec. 9.186/2008 e Dec. 10.501/2012): só as 21 vias do §2º são aplicadas; o Anexo I (mapa do hipercentro) não está publicado e a zona fica desativada. Praça das Rosas (pontas dos incisos I e IX) não existe no OSM: usada a Praça Brasil. Inciso XIX (Rua XV de Novembro entre a Rio Grande do Sul e a Correia Neto) sem correspondência no OSM: pendência.$q$);
